    fullName = `${firstNameTh} ${lastNameTh}`;
  } else if (firstNameEn && lastNameEn) {
    fullName = `${firstNameEn} ${lastNameEn}`;
  }

  // ปั้น string สุดท้าย
  const displayString = `${number} ${fullName}`.trim();

  // ส่งกลับให้ Flow ตัวถัดไปใช้
  return {
    display_string: displayString
  };
