module.exports = async function(data, { services, exceptions } = {}) {
  // เข้าถึง payload จาก trigger
  const citizen_id = "{{read_data_queue.citizen_id}}";
  const hn = "{{read_data_queue.hn}}";

  // สร้างอาเรย์สำหรับเก็บฟิลเตอร์
  let filters = [];

  // ตรวจสอบว่า citizen_id ไม่เป็นค่าว่าง
  if (citizen_id && citizen_id !== "") {
    filters.push({
      "soc_id": {
        "_eq": citizen_id,
        "_neq": ""
      }
    });
  }

  // ตรวจสอบว่า hn ไม่เป็นค่าว่าง
  if (hn && hn !== "") {
    filters.push({
      "hn": {
        "_eq": hn,
        "_neq": ""
      }
    });
  }

  // ถ้าไม่มีฟิลเตอร์ใด ๆ แสดงว่าทั้งสองค่าเป็นค่าว่าง
  if (filters.length === 0) {
    if (exceptions) {
      // โยนข้อผิดพลาดเพื่อหยุดการทำงานของ Flow
      throw new exceptions.Forbidden("กรุณาระบุ citizen_id หรือ hn อย่างน้อยหนึ่งค่า");
    } else {
      // ถ้าไม่มี exceptions ให้โยนข้อผิดพลาดทั่วไป
      throw new Error("กรุณาระบุ citizen_id หรือ hn อย่างน้อยหนึ่งค่า");
    }
  }

  // รวมฟิลเตอร์ด้วยตัวดำเนินการ _or
  const queryFilter = {
    "filter": {
      "_or": filters
    }
  };

  // ส่ง queryFilter กลับไปเพื่อใช้ในขั้นตอนถัดไป
  return queryFilter;
};

