module.exports = async function(data) {
  try {
    // ดึงข้อมูลจาก response
    const data2 = {{request_revisions_appointment.data.data}};

    // ตรวจสอบและกรองข้อมูล null ออก
    const validData = data2.filter(item => item && item.data && item.data.date_updated);

    // ตรวจสอบว่ามีข้อมูลเพียงพอที่จะนำมาเปรียบเทียบหรือไม่
    if (validData.length < 2) {
      throw new Error("Not enough valid data for comparison.");
    }

    // เรียงลำดับข้อมูลตาม date_updated จากเก่าไปใหม่
    const sortedData = validData.sort((a, b) => new Date(a.data.date_updated) - new Date(b.data.date_updated));

    // ดึงสองข้อมูลสุดท้าย
    const secondLast = sortedData[sortedData.length - 2];
    const last = sortedData[sortedData.length - 1];

    // ฟังก์ชั่นสำหรับแยกวันที่
    const getDateOnly = (dateTime) => dateTime.split('T')[0];

    // แยกวันที่จาก datetime
    const lastDate = getDateOnly(last.data.appointment_datetime);
    const secondLastDate = getDateOnly(secondLast.data.appointment_datetime);

    // ตรวจสอบการเปลี่ยนแปลงวันที่
    const dateChanged = lastDate !== secondLastDate;

    // ตรวจสอบการเปลี่ยนแปลง time_slot
    const lastTimeSlot = last.data.time_slot;
    const secondLastTimeSlot = secondLast.data.time_slot;
    const timeSlotChanged = lastTimeSlot !== secondLastTimeSlot;

    // ส่งข้อมูลไปยัง Flow ถัดไป
    return {
      secondLast,
      last,
      dateChanged,
      timeSlotChanged
    };
  } catch (error) {
    console.error("Error in script:", error);
    throw error; // ส่งต่อข้อผิดพลาดไปยัง Flow
  }
};

