module.exports = function(data) {
    // 1. ฟังก์ชันล้างข้อมูล System Fields
    const cleanData = (sourceData, removeFields = []) => {
        if (!sourceData) return null;

        const newData = { ...sourceData };
        const systemFields = [
            'id',
            'user_created', 'date_created',
            'user_updated', 'date_updated',
            'last_saved_at'
        ];

        [...systemFields, ...removeFields].forEach(field => {
            delete newData[field];
        });

        return newData;
    };

    // ฟิลด์ o2m/m2m: item-read คืนเป็น array ของ id แถวลูก ถ้าติดไปตอน create
    // Directus จะ "ย้าย" แถวลูกพวกนั้นมาผูกกับแถวใหม่ (ไม่ใช่ก๊อป)
    // เช่น examination ทำให้ exam เดิมไปผูกกับนัด BX ใหม่
    const appointmentRelationFields = [
        'examination', 'queue', 'referral_form', 'consent_form',
        'appointment_reschedules', 'external_exam_records', 'vital_signs'
    ];
    const examRelationFields = [
        'pacs_sync_infos', 'exam_reason_multi',
        'mam', 'us', 'mammogram_mass', 'mammogram_cal',
        'spots', 'spot_technicians',
        'ultrasound_cyst', 'ultrasound_mass', 'procedure'
    ];

    // 2. เตรียมข้อมูล Appointment
    const appointmentPayload = cleanData({{read_data_appointment}}, appointmentRelationFields);
    if (appointmentPayload) {
        appointmentPayload.appointment_datetime = null;
        appointmentPayload.appointment_status = "ยังไม่ถึงเวลานัด/ยังไม่มา";
        appointmentPayload.request = "bx";
    }

    // 3. เตรียมข้อมูล Examination General
    const examGeneralPayload = cleanData({{read_data_examination_general}}, ['exam']);

    // 4. เตรียมข้อมูล Exam (Parent)
    const mainExamPayload = cleanData(
        {{read_data_exam}},
        ['appointment', 'examination_general', ...examRelationFields]
    );

    if (mainExamPayload) {
        mainExamPayload.exam_date = null;
        mainExamPayload.is_duplicate = true;
    }

    // 5. การประกอบร่าง (Nesting)
    if (appointmentPayload) {
        mainExamPayload.appointment = appointmentPayload;
    }

    if (examGeneralPayload) {
        mainExamPayload.examination_general = [examGeneralPayload];
    }

    return mainExamPayload;
}

