module.exports = async function (data) {
  const billingData = {{read_data_billing}};
  const examCost = {{read_data_examination_cost}};
  const pacsSyncData = {{read_data_pacs_sync_info}} || {};
  const appointmentData = {{read_data_appointment}};
  const discountExam = {{read_data_discount}};
  const location = {{read_data_finance_work.location}}; 

  const total = pacsSyncData.reduce(
  (acc, item) => {
    acc.mamAmount += Number(item.confirm_num_of_mam ?? 0);
    acc.spotAmount += Number(item.confirm_num_of_spot ?? 0);
    acc.implantAmount += Number(item.confirm_num_of_implant ?? 0);
    if (item.modality === "US" && item.is_mark_del === false) {
      acc.ultrasoundAmount += 1;
    }
    return acc;
  },
  { mamAmount: 0, spotAmount: 0, implantAmount: 0, ultrasoundAmount: 0 }
);
  const CopyCDAmount = Array.isArray(appointmentData.front_note_1)
  ? appointmentData.front_note_1.some((note) =>
      note.toLowerCase().includes("รับผลเป็น cd")
    )
    ? 1
    : 0
  : 0;

  const findExamPrice = (exam_type_id) => {
    const exam = examCost.find((item) => item.type === exam_type_id);
    if (!exam) return 0;
      // 1 = TYR
    return Number(location === 1 ? exam.price_tyr : exam.price_ics);
  };

  let a_price = 0,
    b_price = 0,
    c_price = 0,
    d_price = 0;
    e_price = 0;

  const usedTypes = new Set();

  // e_price (Copy CD)
  if(CopyCDAmount > 0) {
    e_price = findExamPrice("H");
    usedTypes.add("H");
  }

  // d_price (Ultrasound)
  if (total.mamAmount > 0 && total.ultrasoundAmount > 0) {
    d_price = findExamPrice("D");
    usedTypes.add("D");
  } else if (total.mamAmount === 0 && total.ultrasoundAmount > 0) {
    d_price = findExamPrice("C");
    usedTypes.add("C");
  }

  // a_price (Mammogram)
  if (total.mamAmount > 0) {
    if (total.mamAmount <= 2) {
      a_price = findExamPrice("A");
      usedTypes.add("A");
    } else {
      a_price = findExamPrice("B");
      usedTypes.add("B");
    }
  }

  // b_price (SPOT)
  if (total.spotAmount > 0) {
    b_price = findExamPrice("E");
    usedTypes.add("E");
  }

  // c_price (Implant)
  if (total.implantAmount > 0 && total.mamAmount > 2) {
    c_price = findExamPrice("F");
    usedTypes.add("F");
  } else if (total.implantAmount > 0 && total.mamAmount > 0) {
    c_price = findExamPrice("G");
    usedTypes.add("G");
  }

  const sortedUsedTypes = Array.from(usedTypes).sort();
  const isOutpatient = appointmentData.care_type !== 2;
  let care_type = appointmentData.care_type;
  const isOvertime = billingData?.is_overtime || false;
  const isForeigner = billingData?.is_foreigner || false;

  let subtotal =
    a_price +
    b_price +
    c_price +
    d_price +
    //e_price +
    (isOutpatient ? 100 : 0) +
    (isOvertime ? 400 : 0);

  let foreigner_fee = isForeigner ? subtotal * 0.25 : 0;
  subtotal += foreigner_fee;

  // Discount logic
  let discountAmount = 0;
  if (Array.isArray(discountExam)) {
    for (const d of discountExam) {
      const types = d.typeList?.split(",").map((x) => x.trim()).sort();
      if (
        types?.length === sortedUsedTypes.length &&
        types.every((v, i) => v === sortedUsedTypes[i])
      ) {
        discountAmount = Number(d.discount || 0);
        break;
      }
    }
  }

  let finalTotal = location === "TYR" ? subtotal : Math.max(0, subtotal - discountAmount);

  const is_invoice_requested = appointmentData.issue_an_invoice;
  const hasOutpatient = Array.isArray(appointmentData.outpatient) && appointmentData.outpatient.length > 0;
  let payment_type = null;
  let can_claim_expense = null;
  let payment_method = null;
  if(appointmentData.payment_type != 0 && appointmentData.payment_type != 8){
      can_claim_expense = true;
      if(care_type == 1){
      	payment_type = appointmentData.payment_type;
      }else{
      	if(appointmentData.payment_type == 1){
        	payment_type = 18;
        }
        else  if(appointmentData.payment_type == 2){payment_type = 19;}
        else  if(appointmentData.payment_type == 3){payment_type = 20;}
        else  if(appointmentData.payment_type == 4){payment_type = 21;}
        else  if(appointmentData.payment_type == 5){payment_type = 22;}
        else if(appointmentData.payment_type == 6){payment_type = 23;}
        else if(appointmentData.payment_type == 7){payment_type = 0;}
      }
  }else if(appointmentData.payment_type == 8){
      can_claim_expense = false;
      if(care_type == 1){
         payment_type = 7;
      }
      else{
      	 payment_type = 24;
      }
  }

  if(hasOutpatient){
      care_type = 3;
      payment_method = 2;
      can_claim_expense = false;
      if(appointmentData.outpatient.includes(1)){
      		payment_type = 8;
      }
      else if(appointmentData.outpatient.includes(2)){
      		payment_type = 9;
      }
      else if(appointmentData.outpatient.includes(3)){
      		payment_type = 10;
      }
      else if(appointmentData.outpatient.includes(4)){
      		payment_type = 11;
      }
      else if(appointmentData.outpatient.includes(5)){
      		payment_type = 16;
      }
      else if(appointmentData.outpatient.includes(6)){
      		payment_type = 17;
      }
  }


  if(payment_type){
     if(payment_type == 1 || payment_type == 2){
         payment_method = 1;
     }
     else if(payment_type == 3 || payment_type == 4 || payment_type == 5 || payment_type == 6
            || payment_type == 18 || payment_type == 19 || payment_type == 20 || payment_type == 21
            || payment_type == 22 || payment_type == 23){
         payment_method = 3;
     }
     else if(payment_type == 7){
         payment_method = 2;
     }
  }

	if(payment_type){
        if(payment_type == 8){
            finalTotal = 0;
        }
    }

  return {
    a: total.mamAmount,
    a_price: a_price.toFixed(2),
    b: total.spotAmount,
    b_price: b_price.toFixed(2),
    c: total.implantAmount,
    c_price: c_price.toFixed(2),
    d: total.ultrasoundAmount,
    d_price: d_price.toFixed(2),
    e: CopyCDAmount,
    e_price: e_price.toFixed(2),
    is_out_patient: isOutpatient,
    is_overtime: isOvertime,
    is_foreigner: isForeigner,
    foreigner_fee: foreigner_fee.toFixed(2),
    discount_amount: discountAmount.toFixed(2),
    total: finalTotal.toFixed(2),
    exam_types_used: sortedUsedTypes,
    care_type: care_type,
    is_invoice_requested: is_invoice_requested,
    can_claim_expense: can_claim_expense,
    payment_type: payment_type,
    payment_method: payment_method,
    hasOutpatient: hasOutpatient,
  };
};

