module.exports = async function(data) {
    let queue = {{read_data_queue}};
	//1 เรียกคิว 2 เสร็จสิ้น
    if (queue.status == 1) {
        return 1; 
    } else if (queue.status == 2) {
        return 2; 
    }else if (queue.status == 0) {
        return 0; 
    }
